commands.command:
install -d -o named -g named -m 0770 /var/named/dynamic
tsig-keygen -a hmac-sha256 ddns-key > /etc/named/ddns.key
chown root:named /etc/named/ddns.key
chmod 0640 /etc/named/ddns.key
cat > /etc/named.conf <<'ANTRIEB_NAMED'
options {
    directory "/var/named";
    listen-on port 53 { any; };
    listen-on-v6 port 53 { any; };
    allow-query { any; };
    recursion no;
    dnssec-validation yes;
    key-directory "/var/named/dynamic";
};

include "/etc/named/ddns.key";

zone "infra.test" IN {
    type master;
    file "dynamic/infra.test";
    update-policy { grant ddns-key zonesub ANY; };
    allow-transfer { 10.100.126.11; 10.100.126.12; };
    also-notify { 10.100.126.11; 10.100.126.12; };
    notify yes;
    dnssec-policy default;
    inline-signing yes;
};
ANTRIEB_NAMED
cat > /var/named/dynamic/infra.test <<'ANTRIEB_ZONE'
$TTL 300
@ IN SOA ns1.infra.test. hostmaster.infra.test. (
    2026100201
    60
    30
    604800
    60 )
  IN NS ns1.infra.test.
  IN NS ns2.infra.test.
  IN NS ns3.infra.test.
ns1 IN A 10.100.126.10
ns2 IN A 10.100.126.11
ns3 IN A 10.100.126.12
app IN A 10.100.126.10
status IN TXT "ready"
ANTRIEB_ZONE
chown named:named /var/named/dynamic/infra.test
chmod 0640 /var/named/dynamic/infra.test
named-checkconf
named-checkzone infra.test /var/named/dynamic/infra.test

cat > /etc/named.conf <<'ANTRIEB_NAMED'
options {
    directory "/var/named";
    listen-on port 53 { any; };
    listen-on-v6 port 53 { any; };
    allow-query { any; };
    recursion no;
    dnssec-validation yes;
};

zone "infra.test" IN {
    type slave;
    file "slaves/infra.test";
    masters { 10.100.126.10; };
    allow-notify { 10.100.126.10; };
    allow-transfer { none; };
    masterfile-format text;
};
ANTRIEB_NAMED
named-checkconf

cat > /etc/named.conf <<'ANTRIEB_NAMED'
options {
    directory "/var/named";
    listen-on port 53 { any; };
    listen-on-v6 port 53 { any; };
    allow-query { any; };
    recursion no;
    dnssec-validation yes;
};

zone "infra.test" IN {
    type slave;
    file "slaves/infra.test";
    masters { 10.100.126.10; };
    allow-notify { 10.100.126.10; };
    allow-transfer { none; };
    masterfile-format text;
};
ANTRIEB_NAMED
named-checkconf
